import{z as s,x as l,o as e,c as p,q as i,j as t,D as a,d as B,s as A,S as n,b as o}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"住房市场","description":"","frontmatter":{"title":"住房市场","date":"2026-09-18T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/ur-housing.md","filePath":"econ/ur-housing.md","lastUpdated":1791063341000}'),d={name:"econ/ur-housing.md"};function c(u,E,h,m,D,f){const r=l("Mermaid");return e(),p("div",null,[E[2]||(E[2]=i('<h1 id="住房市场" tabindex="-1">住房市场 <a class="header-anchor" href="#住房市场" aria-label="Permalink to &quot;住房市场&quot;">​</a></h1><div class="epigraph"><p>住房的供给曲线在地理上是平的，在制度上是竖的；需求来的时候，有弹性的城市盖房子，刚性的城市涨房价。</p><footer>—— 据 Glaeser and Gyourko, The Economic Implications of Housing Supply, Journal of Economic Perspectives 2018；Saiz, The Geographic Determinants of Housing Supply, Quarterly Journal of Economics 2010 整理</footer></div><p><a href="/econ/ur-intra-city">上一课</a>把城市剖面写成租金梯度；本课把时间轴打开：梯度给定之后，需求冲击落进价格还是数量，取决于上一课没写的那个参数——供给弹性。房子是耐用的、异质的、位置固定的消费品加资产，<a href="/econ/housing-asset-consumption">住房与消费</a>讲过它的双重身份；本课讲这个双重身份如何放大波动。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>同一轮降息与人口流入，有的城市表现为建设潮与温和涨价，有的城市表现为房价暴涨与可负担性危机。缺口有三：价格由流量定还是存量定；租售比怎么读；信贷怎么把房价变成放大器。只盯「全国平均房价」会把三个缺口全读错——平均数掩盖了城市间的分岔，而分岔才是住房市场的全部信息。</p><h3 id="存量-流量与用户成本" tabindex="-1">存量-流量与用户成本 <a class="header-anchor" href="#存量-流量与用户成本" aria-label="Permalink to &quot;存量-流量与用户成本&quot;">​</a></h3><p>方法是把市场拆成两层。流量层：价格即时调整，存量按建设周期缓慢变化；长期里价格被边际供给成本托底——Glaeser 与 Gyourko 的口径是，房价持续高于重置成本的部分，是土地与许可的租金，不是建材涨价。供给弹性由两层决定：地理（Saiz 2010 用坡度、水域与地形算出不可开发份额，把地理从管制里剥出来）与管制（分区、许可）。资产层是用户成本恒等式：\\(R=P\\,(i+\\tau_p+\\delta-\\pi_P)\\)，其中 \\(\\pi_P\\) 是预期房价增速；租售比 \\(P/R\\) 因此对实际利率与预期租金增速高度敏感（Poterba 1984 的税收补贴分析即由此入手）。</p><p><span class="marginnote">租售比的算术：实际利率 5%、租金零增长时 \\(P/R\\approx20\\)；利率降到 4%、预期租金增速 2% 时 \\(P/R\\) 可站上 50。同一处房子，房租没动，价格可以翻倍还多——先算机械效应，再谈情绪与泡沫。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>抵押品通道把资产层接回信贷：房价上涨抬抵押品价值、放松借贷约束、再推房价，与<a href="/econ/collateral-house-prices">抵押品与房价</a>同一机制，杠杆决定环是温和的还是爆裂的。分配端靠过滤机制：富人换新房，旧房逐级下滤给低收入者；掐断高端新建，等于切断链条末端的隐形供给，穷人面对的存量更旧更贵。总量端是 Hsieh 与 Moretti 2019：1964–1980 年美国城市间名义工资在收敛，1980 年代起收敛停摆——高生产率城市因住房约束拒绝迁入者，全美产出低于无约束反事实。上一课的聚集增益，被本课的供给约束吃掉。</p>',10)),(e(),t(n,null,{default:a(()=>[A(r,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20DEM%5B%22%E9%9C%80%E6%B1%82%E5%86%B2%E5%87%BB%3A%20%E9%99%8D%E6%81%AF%2F%E4%BA%BA%E5%8F%A3%E6%B5%81%E5%85%A5%22%5D%20--%3E%20ELC%5B%22%E4%BE%9B%E7%BB%99%E5%BC%B9%E6%80%A7%E9%AB%98%22%5D%0A%20%20DEM%20--%3E%20INE%5B%22%E4%BE%9B%E7%BB%99%E5%BC%B9%E6%80%A7%E4%BD%8E%22%5D%0A%20%20ELC%20--%3E%20QTY%5B%22%E6%95%B0%E9%87%8F%E5%93%8D%E5%BA%94%3A%20%E5%BB%BA%E8%AE%BE%E6%BD%AE%2C%20%E4%BB%B7%E6%A0%BC%E6%B8%A9%E5%92%8C%22%5D%0A%20%20INE%20--%3E%20PR%5B%22%E4%BB%B7%E6%A0%BC%E5%93%8D%E5%BA%94%3A%20%E6%88%BF%E4%BB%B7%E6%9A%B4%E6%B6%A8%22%5D%0A%20%20PR%20--%3E%20COL%5B%22%E6%8A%B5%E6%8A%BC%E5%93%81%E4%BB%B7%E5%80%BC%E4%B8%8A%E5%8D%87%22%5D%0A%20%20COL%20--%3E%20CRED%5B%22%E5%80%9F%E8%B4%B7%E7%BA%A6%E6%9D%9F%E6%94%BE%E6%9D%BE%22%5D%0A%20%20CRED%20--%3E%20PR%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[B(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=o("h2",{id:"机制",tabindex:"-1"},[B("机制 "),o("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=o("p",null,"把三课连起来读：第一课说聚集让高密度城市更值钱，本课说约束让这份值钱只落进房价不落进人头。读房价数据时最容易犯的错有两类：一是把租售比当泡沫的充分统计，忘了利率与预期的机械通道；二是把供给弹性当常数，忘了地理是慢变量、管制是政策变量，同一个城市十年前的弹性未必是今天的弹性。",-1)),(e(),t(n,null,{default:a(()=>[A(r,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20LR%0A%20%20N%5B%22%E5%AF%8C%E4%BA%BA%E6%96%B0%E5%BB%BA%E9%AB%98%E7%AB%AF%E6%88%BF%22%5D%20--%3E%20M1%5B%22%E5%AF%8C%E4%BA%BA%E6%90%AC%E5%87%BA%E4%B8%AD%E6%A1%A3%E6%88%BF%22%5D%0A%20%20M1%20--%3E%20M2%5B%22%E4%B8%AD%E4%BA%A7%E6%8E%A5%E6%89%8B%E8%85%BE%E5%87%BA%E7%9A%84%E6%88%BF%E5%AD%90%22%5D%0A%20%20M2%20--%3E%20M3%5B%22%E6%97%A7%E6%88%BF%E7%BB%A7%E7%BB%AD%E4%B8%8B%E6%BB%A4%E7%BB%99%E4%BD%8E%E6%94%B6%E5%85%A5%E5%AE%B6%E5%BA%AD%22%5D%0A%20%20M3%20--%3E%20TAIL%5B%22%E9%93%BE%E6%9D%A1%E6%9C%AB%E7%AB%AF%E5%B0%B1%E6%98%AF%E7%A9%B7%E4%BA%BA%E7%9A%84%E9%9A%90%E5%BD%A2%E4%BE%9B%E7%BB%99%22%5D%0A%20%20BLK%5B%22%E6%8E%90%E6%96%AD%E9%AB%98%E7%AB%AF%E6%96%B0%E5%BB%BA%22%5D%20--%3E%20CUT%5B%22%E8%BF%87%E6%BB%A4%E6%BA%90%E5%A4%B4%E6%96%AD%E4%BE%9B%22%5D%0A%20%20CUT%20--%3E%20END%5B%22%E5%AD%98%E9%87%8F%E6%9B%B4%E6%97%A7%E3%80%81%E6%9B%B4%E8%B4%B5%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[B(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=i('<p><span class="marginnote">「供给弹性」可以翻译成：房价每涨 1%，开发商愿意多盖百分之几的房子。有弹性的城市像一片开阔的操场，需求来了向四面八方扩；无弹性的城市像被墙围住的院子——墙有两堵，一堵是地理（山、海、湿地），一堵是管制（分区、许可），后者是人砌的，可以拆。</span></p><p><span class="marginnote">数字实例：一套房的建材加人工重置成本 50 万，市价卖 200 万，中间 150 万的差价不是「房子变贵了」，而是这块地加上盖房许可证的租金。看一座城市有没有供给约束，就盯这个差价是不是长期存在。</span></p><p><span class="marginnote">常见误区：「不许盖豪宅，穷人就住得起」。过滤机制说反了：豪宅是下滤链条的源头，源头断供，中产腾不出旧房，穷人接到的反而是更旧更贵的存量。类似地，「租售比高 = 泡沫」也快了一步——利率一降租售比机械上升，先算机械效应再谈情绪。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>资产定价工具用在住房上要加约束：房子不可分割、自住有消费收益、交易成本高，套利远弱于金融资产，现值公式的残差不该全归给风险溢价。按揭利息扣除的归宿落在房价还是家庭，与<a href="/econ/tax-incidence">税收归宿</a>同一问法，本课不展开。房价-信贷的联合波动留给宏观金融课程；这里只钉一句：判断一座城市的房价，先看它的供给曲线，再看它的人民，最后才看它的故事。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>存量-流量：价格即时、存量缓慢；长期价格贴着边际供给成本。</li><li>供给弹性等于地理加管制；Saiz 用不可开发份额先剥出地理。</li><li>租售比对利率与预期租金增速敏感，静态读法会把机械效应当泡沫。</li><li>过滤是低收入住房的隐形供给线，掐断新建伤在链条末端。</li><li>聚集增益被住房约束截断：Hsieh–Moretti 的空间错配是全国总量问题。</li><li>出处：Glaeser–Gyourko, <em>JEP</em> 2018；Saiz, <em>QJE</em> 2010；Poterba, <em>QJE</em> 1984；Hsieh–Moretti, <em>AEJ: Macro</em> 2019。</li></ul>',7))])}const P=s(d,[["render",c]]);export{C as __pageData,P as default};
